internal static class DofusInstructionsAcceptance {
 internal static string Fixture(int id=37){return new JavaScriptSerializer().Serialize(new{ganymedeGuide=new{id=id,name="Guide de test Ganymède",author="Auteur fictif",description="Test uniquement",steps=new[]{new{id=301,name="",order=1,map="Carte de test",pos_x=-1,pos_y=2,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><div><p>Instruction intégrée de test.</p></div></div><div data-type=\"quest-block\" questname=\"Autre quête\">Ne pas associer ce texte.</div>"},new{id=302,name="",order=2,map="Carte de test",pos_x=0,pos_y=0,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><p>Instruction suivante de test.</p></div>"}}}});}
 internal static void Test(string folder){CoordinateLinks.Test();var store=new Store(Path.Combine(folder,"ganymede-main"));var c=new DofusCharacter{id="personnage",name="Test",classCode="Sacri",guide="parcours-exemple"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;store.Save();var doc=TougliReader.Parse(DofusAcceptance.Sample,c);var step=doc.Steps.First(s=>s.QuestId=="10");TougliReader.Cache(store,"ganymede-37",Fixture());var index=QuestInstructionIndex.Load(store);if(index.Match(step).Count!=2||index.Match(step).Any(s=>s.Details.Contains("Ne pas associer")))throw new Exception("Association et séparation des blocs de quête");if(index.Match(new TougliStep{QuestId="10",Title="Premiere quete fictive"}).Count!=2||index.Match(new TougliStep{QuestId="10",Title="Première quête fictiv"}).Any())throw new Exception("Correspondance exacte normalisée");string key=QuestInstructionIndex.CursorKey(store.Value,step,"ganymede-37");PersonalWorkflows.Change(store,()=>store.Value.instructions.cursors[key]=index.Match(step)[1].Key);var reopened=new Store(store.Root);if(reopened.Value.instructions.cursors[key]!=index.Match(step)[1].Key||DofusCompanion.Find(reopened.Value,c)!=null)throw new Exception("Sous-instruction indépendante de la validation");store.Export(Path.Combine(folder,"instructions-export.json"));var imported=new Store(Path.Combine(folder,"instructions-import"));imported.Import(Path.Combine(folder,"instructions-export.json"));if(imported.Value.instructions.cursors[key]!=store.Value.instructions.cursors[key])throw new Exception("Import instructions");var file=Path.Combine(folder,"instructions.mespace");FullBackup.Export(store,file);var target=new Store(Path.Combine(folder,"instructions-restore"));using(var plan=FullBackup.Prepare(target,file))FullBackup.Commit(target,plan);if(target.Value.instructions.cursors[key]!=store.Value.instructions.cursors[key]||Directory.Exists(Path.Combine(target.Root,"TougliCache")))throw new Exception("Sauvegarde progression sans guides source");File.WriteAllText(Path.Combine(folder,"GANYMEDE_MAIN_PASS.txt"),"PASS: exact names with normalization; unrelated quest block exclusion; independent instruction cursor; restart; JSON import; full backup and restore without redistributing source guides.");}
}
